			[{ routeId: "item-uuid-1" }, "manage", "item-uuid-1"],
		] as const)("routes %o to %s", (start, mode, managedId) => {
			const h = harness(start);
			expect(h.view()).toMatchObject({ mode, managedId });
		});

		it("follows route changes, and ignores a repeated route", () => {
			const h = harness();
